-- Behavioural Therapy — 60-item informal skills assessment
-- Reference: BT_Assessment_Tool_Model(1).pdf (assessment), BT_New_Client_Case_History.pdf (separate intake).
-- Creates an assignable published custom assessment without altering existing templates or student records.
-- The current custom-assessment UI has a single NA option. N/O vs N/A must be specified in remarks.
INSERT INTO public.custom_assessment_templates
 (title,description,level,structure,status,created_by,scoring_guide)
SELECT
 'Behavioural Therapy — Informal Skills Assessment',
 'Informal, non-standardized Behavioural Therapy Assessment based on the attached BT Assessment Tool Model. 60 descriptive skill items across nine domains. To be administered by an appropriately qualified assessor with child assent, in context. Rating 0 = not demonstrated; 1 = full assistance; 2 = partial assistance; 3 = independent. The portal offers only NA for exclusions; identify Not Observed (N/O) versus Not Applicable (N/A) in the remarks. Exclude NA from applicable maximum; results have no diagnostic or severity cut-offs. Keep case history as a separate confidential intake record.',
 'all',
 '[{"id":"s_bt_skills","title":"Behavioural Therapy — Informal Skills Assessment","categories":[{"id":"c_bt_A","title":"A. Attention and attending","questions":[{"id":"q_BT_A_01","text":"Responds to name","text_ml":"പേര് വിളിക്കുമ്പോൾ പ്രതികരിക്കുന്നു","response_type":"rating"},{"id":"q_BT_A_02","text":"Joint attention","text_ml":"സംയുക്ത ശ്രദ്ധ","response_type":"rating"},{"id":"q_BT_A_03","text":"Engages in activity","text_ml":"പ്രവർത്തനത്തിൽ പങ്കെടുക്കുന്നു","response_type":"rating"},{"id":"q_BT_A_04","text":"Attention span (record duration)","text_ml":"ശ്രദ്ധയുടെ ദൈർഘ്യം (സമയം രേഖപ്പെടുത്തുക)","response_type":"rating"},{"id":"q_BT_A_05","text":"Task completion","text_ml":"പ്രവർത്തനം പൂർത്തിയാക്കുന്നു","response_type":"rating"},{"id":"q_BT_A_06","text":"Responds to instructions","text_ml":"നിർദേശങ്ങളോട് പ്രതികരിക്കുന്നു","response_type":"rating"}]},{"id":"c_bt_B","title":"B. Receptive communication","questions":[{"id":"q_BT_B_01","text":"Follows one-step instructions","text_ml":"ഒറ്റഘട്ട നിർദേശങ്ങൾ പാലിക്കുന്നു","response_type":"rating"},{"id":"q_BT_B_02","text":"Follows two-step instructions","text_ml":"രണ്ടുഘട്ട നിർദേശങ്ങൾ പാലിക്കുന്നു","response_type":"rating"},{"id":"q_BT_B_03","text":"Identifies familiar objects","text_ml":"പരിചിത വസ്തുക്കൾ തിരിച്ചറിയുന്നു","response_type":"rating"},{"id":"q_BT_B_04","text":"Identifies body parts","text_ml":"ശരീരഭാഗങ്ങൾ തിരിച്ചറിയുന്നു","response_type":"rating"},{"id":"q_BT_B_05","text":"Understands action words","text_ml":"പ്രവർത്തന പദങ്ങൾ മനസ്സിലാക്കുന്നു","response_type":"rating"},{"id":"q_BT_B_06","text":"Understands simple questions","text_ml":"ലളിത ചോദ്യങ്ങൾ മനസ്സിലാക്കുന്നു","response_type":"rating"}]},{"id":"c_bt_C","title":"C. Expressive communication","questions":[{"id":"q_BT_C_01","text":"Expresses basic needs","text_ml":"അടിസ്ഥാന ആവശ്യങ്ങൾ പ്രകടിപ്പിക്കുന്നു","response_type":"rating"},{"id":"q_BT_C_02","text":"Requests preferred items","text_ml":"ഇഷ്ടവസ്തുക്കൾ ആവശ്യപ്പെടുന്നു","response_type":"rating"},{"id":"q_BT_C_03","text":"Labels objects","text_ml":"വസ്തുക്കളുടെ പേര് പറയുന്നു","response_type":"rating"},{"id":"q_BT_C_04","text":"Vocal imitation if applicable","text_ml":"ശബ്ദാനുകരണം (ബാധകമെങ്കിൽ)","response_type":"rating"},{"id":"q_BT_C_05","text":"Answers questions if applicable","text_ml":"ചോദ്യങ്ങൾക്ക് ഉത്തരം പറയുന്നു (ബാധകമെങ്കിൽ)","response_type":"rating"},{"id":"q_BT_C_06","text":"Requests help or a break","text_ml":"സഹായമോ ഇടവേളയോ ആവശ്യപ്പെടുന്നു","response_type":"rating"},{"id":"q_BT_C_07","text":"Communicates discomfort or refusal","text_ml":"അസൗകര്യമോ വിസമ്മതമോ അറിയിക്കുന്നു","response_type":"rating"}]},{"id":"c_bt_D","title":"D. Imitation","questions":[{"id":"q_BT_D_01","text":"Gross motor imitation","text_ml":"വലിയ ചലനങ്ങളുടെ അനുകരണം","response_type":"rating"},{"id":"q_BT_D_02","text":"Fine motor imitation","text_ml":"ചെറിയ ചലനങ്ങളുടെ അനുകരണം","response_type":"rating"},{"id":"q_BT_D_03","text":"Object imitation","text_ml":"വസ്തുക്കൾ ഉപയോഗിച്ചുള്ള അനുകരണം","response_type":"rating"},{"id":"q_BT_D_04","text":"Gesture imitation","text_ml":"ആംഗ്യാനുകരണം","response_type":"rating"},{"id":"q_BT_D_05","text":"Vocal imitation","text_ml":"ശബ്ദാനുകരണം","response_type":"rating"}]},{"id":"c_bt_E","title":"E. Cognitive and learning","questions":[{"id":"q_BT_E_01","text":"Object matching","text_ml":"വസ്തു പൊരുത്തപ്പെടുത്തൽ","response_type":"rating"},{"id":"q_BT_E_02","text":"Picture matching","text_ml":"ചിത്രം പൊരുത്തപ്പെടുത്തൽ","response_type":"rating"},{"id":"q_BT_E_03","text":"Sorting","text_ml":"വർഗീകരണം","response_type":"rating"},{"id":"q_BT_E_04","text":"Colour identification","text_ml":"നിറം തിരിച്ചറിയൽ","response_type":"rating"},{"id":"q_BT_E_05","text":"Shape identification","text_ml":"ആകൃതി തിരിച്ചറിയൽ","response_type":"rating"},{"id":"q_BT_E_06","text":"Sequencing","text_ml":"ക്രമീകരണം","response_type":"rating"},{"id":"q_BT_E_07","text":"Memory skills","text_ml":"ഓർമ്മശക്തി","response_type":"rating"},{"id":"q_BT_E_08","text":"Problem solving","text_ml":"പ്രശ്നപരിഹാരം","response_type":"rating"}]},{"id":"c_bt_F","title":"F. Social skills","questions":[{"id":"q_BT_F_01","text":"Responds to greetings","text_ml":"അഭിവാദ്യങ്ങൾക്ക് പ്രതികരിക്കുന്നു","response_type":"rating"},{"id":"q_BT_F_02","text":"Initiates interaction","text_ml":"ഇടപെടൽ ആരംഭിക്കുന്നു","response_type":"rating"},{"id":"q_BT_F_03","text":"Sharing","text_ml":"പങ്കിടൽ","response_type":"rating"},{"id":"q_BT_F_04","text":"Turn-taking","text_ml":"ഊഴം പാലിക്കൽ","response_type":"rating"},{"id":"q_BT_F_05","text":"Peer interaction","text_ml":"സമപ്രായക്കാരുമായി ഇടപെടൽ","response_type":"rating"},{"id":"q_BT_F_06","text":"Group participation","text_ml":"സംഘപങ്കാളിത്തം","response_type":"rating"},{"id":"q_BT_F_07","text":"Cooperative activities","text_ml":"സഹകരണ പ്രവർത്തനങ്ങൾ","response_type":"rating"},{"id":"q_BT_F_08","text":"Respects personal boundaries","text_ml":"വ്യക്തിപരമായ അതിരുകൾ മാനിക്കുന്നു","response_type":"rating"}]},{"id":"c_bt_G","title":"G. Play skills","questions":[{"id":"q_BT_G_01","text":"Independent play","text_ml":"സ്വതന്ത്ര കളി","response_type":"rating"},{"id":"q_BT_G_02","text":"Functional play","text_ml":"പ്രവർത്തനപരമായ കളി","response_type":"rating"},{"id":"q_BT_G_03","text":"Parallel play","text_ml":"സമാന്തര കളി","response_type":"rating"},{"id":"q_BT_G_04","text":"Pretend play","text_ml":"സാങ്കൽപ്പിക കളി","response_type":"rating"},{"id":"q_BT_G_05","text":"Cooperative play","text_ml":"സഹകരണ കളി","response_type":"rating"},{"id":"q_BT_G_06","text":"Constructive play","text_ml":"നിർമാണാത്മക കളി","response_type":"rating"}]},{"id":"c_bt_H","title":"H. Emotional regulation","questions":[{"id":"q_BT_H_01","text":"Waiting with support","text_ml":"പിന്തുണയോടെ കാത്തിരിക്കുന്നു","response_type":"rating"},{"id":"q_BT_H_02","text":"Transitions between activities","text_ml":"പ്രവർത്തനങ്ങൾ മാറുന്നു","response_type":"rating"},{"id":"q_BT_H_03","text":"Expresses emotions","text_ml":"വികാരങ്ങൾ പ്രകടിപ്പിക്കുന്നു","response_type":"rating"},{"id":"q_BT_H_04","text":"Manages frustration with support","text_ml":"പിന്തുണയോടെ നിരാശ കൈകാര്യം ചെയ്യുന്നു","response_type":"rating"},{"id":"q_BT_H_05","text":"Communicates refusal","text_ml":"വിസമ്മതം അറിയിക്കുന്നു","response_type":"rating"},{"id":"q_BT_H_06","text":"Copes with changes","text_ml":"മാറ്റങ്ങളുമായി പൊരുത്തപ്പെടുന്നു","response_type":"rating"},{"id":"q_BT_H_07","text":"Uses regulation strategies","text_ml":"നിയന്ത്രണ തന്ത്രങ്ങൾ ഉപയോഗിക്കുന്നു","response_type":"rating"}]},{"id":"c_bt_I","title":"I. Activities of daily living","questions":[{"id":"q_BT_I_01","text":"Eating","text_ml":"ഭക്ഷണം കഴിക്കൽ","response_type":"rating"},{"id":"q_BT_I_02","text":"Drinking","text_ml":"കുടിക്കൽ","response_type":"rating"},{"id":"q_BT_I_03","text":"Dressing","text_ml":"വസ്ത്രധാരണം","response_type":"rating"},{"id":"q_BT_I_04","text":"Toileting","text_ml":"ടോയ്‌ലറ്റ് ഉപയോഗം","response_type":"rating"},{"id":"q_BT_I_05","text":"Handwashing","text_ml":"കൈകഴുകൽ","response_type":"rating"},{"id":"q_BT_I_06","text":"Brushing teeth","text_ml":"പല്ലുതേക്കൽ","response_type":"rating"},{"id":"q_BT_I_07","text":"Organizing belongings","text_ml":"സാധനങ്ങൾ ക്രമീകരിക്കൽ","response_type":"rating"}]}]}]'::jsonb,
 'published',
 ur.user_id,
 '{"0":{"en":"Not demonstrated","ml":"പ്രകടമാക്കിയില്ല"},"1":{"en":"Full assistance","ml":"പൂർണ്ണ സഹായം"},"2":{"en":"Partial assistance","ml":"ഭാഗിക സഹായം"},"3":{"en":"Independent","ml":"സ്വതന്ത്രമായി"},"NA":{"en":"Not observed or not applicable (specify N/O or N/A in remarks)","ml":"നിരീക്ഷിച്ചില്ല അല്ലെങ്കിൽ ബാധകമല്ല (കുറിപ്പിൽ N/O അഥവാ N/A വ്യക്തമാക്കുക)"}}'::jsonb
FROM public.user_roles ur
JOIN auth.users au ON au.id=ur.user_id
WHERE ur.role IN ('owner','teacher')
  AND NOT EXISTS (SELECT 1 FROM public.custom_assessment_templates t WHERE t.title='Behavioural Therapy — Informal Skills Assessment')
ORDER BY CASE WHEN ur.role='owner' THEN 0 ELSE 1 END, ur.created_at ASC
LIMIT 1;